172→/**
173→ * Load the recycle bin metadata from IPNS.
174→ *
175→ * If no bin IPNS record exists yet (first login / never deleted anything),
176→ * returns an empty BinState so that deleteToBin can create the first record.
177→ * The old bin service handled this by creating in-memory-only empty state;
178→ * the SDK must do the same to avoid "Bin not loaded" errors on first delete.
179→ *
180→ * @returns Current bin state (never null — empty state if no record exists)
181→ */
182→export async function loadBin(params: { binCtx: BinOperationContext }): Promise<BinState> {
183→  const loaded = await loadBinMetadataInternal({
184→    userPrivateKey: params.binCtx.userPrivateKey,
185→    ctx: params.binCtx.ctx,
186→  });
187→
188→  if (!loaded) {
189→    // No bin IPNS record — auto-repair by publishing empty bin.
190→    // Safe: resolveIpnsRecord throws on transient errors (500, network),
191→    // returns null only for definitive "not found" (API success=false or 404).
192→    // IPNS sequence number ordering prevents overwriting a higher-sequence record.
193→    console.warn('[CipherBox] Bin IPNS record not found — auto-repairing with empty bin');
194→    const binIpns = await deriveBinIpnsKeypair(params.binCtx.userPrivateKey);
195→    const emptyMetadata: RecycleBinMetadata = {
196→      version: BIN_METADATA_VERSION,
197→      sequenceNumber: 1,
198→      entries: [],
199→    };
200→    // Publish empty bin to establish the IPNS record (with retry/verify)
201→    await saveBinMetadata({ metadata: emptyMetadata, binCtx: params.binCtx });
202→    return {
203→      entries: [],
204→      sequenceNumber: 1,
205→      ipnsName: binIpns.ipnsName,
206→    };
207→  }
208→
209→  return {
210→    entries: loaded.metadata.entries,
211→    sequenceNumber: loaded.metadata.sequenceNumber,
212→    ipnsName: loaded.ipnsName,
213→  };
214→}
