216→/**
217→ * Add item to recycle bin.
218→ *
219→ * Removes the item from the folder metadata (via deleteFromFolder),
220→ * creates a BinEntry, appends to bin metadata, and publishes both.
221→ *
222→ * @returns The removed item from the folder
223→ */
224→export async function addToBin(params: {
225→  folderIpnsName: string;
226→  childId: string;
227→  parentPath: string;
228→  folderTree: FolderTree;
229→  binState: BinState;
230→  binCtx: BinOperationContext;
231→}): Promise<{ removedItem: FolderChild; updatedBinState: BinState }> {
232→  const folder = params.folderTree.get(params.folderIpnsName);
233→  if (!folder) throw new Error('Folder not loaded');
234→
235→  // 1. Remove item from folder metadata
236→  const { updatedChildren, removedItem } = sdkCore.deleteFromFolder({
237→    children: folder.children,
238→    childId: params.childId,
239→  });
240→
241→  // 2. Publish updated folder metadata
242→  const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
243→    children: updatedChildren,
244→    folderKey: folder.folderKey,
245→    ipnsPrivateKey: folder.ipnsKeypair.privateKey,
246→    ipnsName: params.folderIpnsName,
247→    sequenceNumber: folder.sequenceNumber,
248→    ctx: params.binCtx.ctx,
249→  });
250→
251→  // 3. Update folder state
252→  folder.children = updatedChildren;
253→  folder.sequenceNumber = newSequenceNumber;
254→  folder.lastLoadedAt = Date.now();
255→  params.folderTree.set(params.folderIpnsName, folder);
256→
257→  // 4. Build bin entry
258→  const isFile = removedItem.type === 'file';
259→  const entry: BinEntry = {
260→    id: crypto.randomUUID(),
261→    itemType: isFile ? 'file' : 'folder',
262→    name: removedItem.name,
263→    originalParentIpnsName: params.folderIpnsName,
264→    originalPath: params.parentPath,
265→    deletedAt: Date.now(),
266→    size: 0,
267→    mimeType: '',
268→    filePointer: isFile ? (removedItem as FilePointer) : undefined,
269→    folderEntry: !isFile ? (removedItem as FolderEntry) : undefined,
270→  };
271→
272→  // 5. Update bin metadata and publish
273→  const updatedEntries = [...params.binState.entries, entry];
274→  const newBinSeq = params.binState.sequenceNumber + 1;
275→
276→  const metadata: RecycleBinMetadata = {
277→    version: BIN_METADATA_VERSION,
278→    sequenceNumber: newBinSeq,
279→    entries: updatedEntries,
280→  };
281→
282→  await saveBinMetadata({ metadata, binCtx: params.binCtx });
283→
284→  const updatedBinState: BinState = {
285→    entries: updatedEntries,
286→    sequenceNumber: newBinSeq,
287→    ipnsName: params.binState.ipnsName,
288→  };
289→
290→  return { removedItem, updatedBinState };
291→}
