293→/**
294→ * Restore an item from the recycle bin back to a folder.
295→ *
296→ * Removes the entry from bin metadata, adds the preserved FolderChild
297→ * back to the target folder's children, and publishes both.
298→ */
299→export async function restoreFromBin(params: {
300→  entryId: string;
301→  targetFolderIpnsName: string;
302→  folderTree: FolderTree;
303→  binState: BinState;
304→  binCtx: BinOperationContext;
305→}): Promise<{ restoredItem: FolderChild; updatedBinState: BinState }> {
306→  // 1. Find the bin entry
307→  const entry = params.binState.entries.find((e) => e.id === params.entryId);
308→  if (!entry) throw new Error('Bin entry not found');
309→
310→  // 2. Get the FolderChild to restore
311→  let child: FolderChild;
312→  if (entry.itemType === 'file' && entry.filePointer) {
313→    child = { ...entry.filePointer, modifiedAt: Date.now() };
314→  } else if (entry.itemType === 'folder' && entry.folderEntry) {
315→    child = { ...entry.folderEntry, modifiedAt: Date.now() };
316→  } else {
317→    throw new Error('Bin entry has no stored item reference');
318→  }
319→
320→  // 3. Add child back to target folder
321→  const targetFolder = params.folderTree.get(params.targetFolderIpnsName);
322→  if (!targetFolder) throw new Error('Target folder not loaded');
323→
324→  // Handle name collisions
325→  const existingNames = new Set(targetFolder.children.map((c) => c.name));
326→  if (existingNames.has(child.name)) {
327→    let newName = `${child.name} (restored)`;
328→    let counter = 2;
329→    while (existingNames.has(newName)) {
330→      newName = `${child.name} (restored ${counter})`;
331→      counter++;
332→    }
333→    child = { ...child, name: newName };
334→  }
335→
336→  const updatedFolderChildren = [...targetFolder.children, child];
337→
338→  // 4. Publish updated folder metadata
339→  const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
340→    children: updatedFolderChildren,
341→    folderKey: targetFolder.folderKey,
342→    ipnsPrivateKey: targetFolder.ipnsKeypair.privateKey,
343→    ipnsName: params.targetFolderIpnsName,
344→    sequenceNumber: targetFolder.sequenceNumber,
345→    ctx: params.binCtx.ctx,
346→  });
347→
348→  // 5. Update folder state
349→  targetFolder.children = updatedFolderChildren;
350→  targetFolder.sequenceNumber = newSequenceNumber;
351→  targetFolder.lastLoadedAt = Date.now();
352→  params.folderTree.set(params.targetFolderIpnsName, targetFolder);
353→
354→  // 6. Remove entry from bin and publish
355→  const remainingEntries = params.binState.entries.filter((e) => e.id !== params.entryId);
356→  const newBinSeq = params.binState.sequenceNumber + 1;
357→
358→  const metadata: RecycleBinMetadata = {
359→    version: BIN_METADATA_VERSION,
360→    sequenceNumber: newBinSeq,
361→    entries: remainingEntries,
362→  };
363→
364→  await saveBinMetadata({ metadata, binCtx: params.binCtx });
365→
366→  const updatedBinState: BinState = {
367→    entries: remainingEntries,
368→    sequenceNumber: newBinSeq,
369→    ipnsName: params.binState.ipnsName,
370→  };
371→
372→  return { restoredItem: child, updatedBinState };
373→}
