211→// ---------------------------------------------------------------------------
212→// Post-upload / post-create share key propagation
213→// ---------------------------------------------------------------------------
214→
215→/**
216→ * Ensure sent shares cache is fresh (fetched within last 30s).
217→ * Returns the current sent shares array.
218→ */
219→async function ensureFreshSentShares(): Promise<SentShare[]> {
220→  const store = useShareStore.getState();
221→  if (store.lastSentFetchedAt && Date.now() - store.lastSentFetchedAt < 30_000) {
222→    return store.sentShares;
223→  }
224→  // Re-wrapping needs the full set — paginate through all pages
225→  const allShares = await fetchAllSentShares();
226→  useShareStore.getState().setSentShares(allShares);
227→  return allShares;
228→}
229→
230→/**
231→ * Fetch ALL sent shares by paginating through the API.
232→ * The API enforces a max limit of 100 per page.
233→ */
234→async function fetchAllSentShares(): Promise<SentShare[]> {
235→  const pageSize = 100;
236→  let offset = 0;
237→  const allShares: SentShare[] = [];
238→
239→  while (true) {
240→    const { shares, total } = await fetchSentShares(pageSize, offset);
241→    allShares.push(...shares);
242→    offset += shares.length;
243→    if (offset >= total || shares.length === 0) break;
244→  }
245→
246→  return allShares;
247→}
