251→ * Used to decide whether post-upload re-wrapping is needed.
252→ */
253→export async function hasActiveShares(folderIpnsName: string): Promise<boolean> {
254→  const shares = await ensureFreshSentShares();
255→  return shares.some((s) => s.ipnsName === folderIpnsName);
256→}
