258→/**
259→ * Find active shares that cover a given folder, including ancestor shares.
260→ * A folder is "covered" if it or any of its ancestor folders is shared.
261→ *
262→ * Walks the ancestor chain and checks each folder's IPNS name against sent shares.
263→ *
264→ * @param folderIpnsName - IPNS name of the current folder
265→ * @param folders - Current folder tree from the folder store
266→ * @param currentFolderId - ID of the current folder in the tree
267→ * @returns Array of sent shares covering this folder (may be from ancestor)
268→ */
269→export async function findCoveringShares(
270→  folderIpnsName: string,
271→  folders: Record<string, FolderNode>,
272→  currentFolderId: string | null
273→): Promise<SentShare[]> {
274→  const shares = await ensureFreshSentShares();
275→  if (shares.length === 0) return [];
276→
277→  // Collect all IPNS names from this folder up to root
278→  const ipnsNames = new Set<string>();
279→  ipnsNames.add(folderIpnsName);
280→
281→  let walkId = currentFolderId;
282→  while (walkId) {
283→    const node = folders[walkId];
284→    if (!node) break;
285→    ipnsNames.add(node.ipnsName);
286→    walkId = node.parentId;
287→  }
288→
289→  return shares.filter((s) => ipnsNames.has(s.ipnsName));
290→}
