292→/**
293→ * After adding a file or subfolder to a shared folder, re-wrap the new key
294→ * for all existing share recipients.
295→ *
296→ * This is a fire-and-forget operation -- failures are logged but don't block
297→ * the primary upload/create flow.
298→ *
299→ * IMPORTANT: Callers are responsible for zeroing `newItems[*].plaintextKey`
300→ * after this function completes. This function does NOT zero the keys because
301→ * some callers (e.g., subfolder creation) keep the key alive in the store.
302→ * Use a `finally` block to ensure zeroing even on errors.
303→ *
304→ * @param params.folderIpnsName - IPNS name of the folder being modified
305→ * @param params.folders - Current folder tree from the store
306→ * @param params.currentFolderId - ID of the current folder in the tree
307→ * @param params.newItems - New items whose keys need re-wrapping
308→ */
309→export async function reWrapForRecipients(params: {
310→  folderIpnsName: string;
311→  folders: Record<string, FolderNode>;
312→  currentFolderId: string | null;
313→  newItems: Array<{
314→    keyType: 'file' | 'folder';
315→    itemId: string;
316→    plaintextKey: Uint8Array;
317→  }>;
318→}): Promise<{ failedRecipients: string[] }> {
319→  const coveringShares = await findCoveringShares(
320→    params.folderIpnsName,
321→    params.folders,
322→    params.currentFolderId
323→  );
324→
325→  if (coveringShares.length === 0) return { failedRecipients: [] };
326→
327→  const failedRecipients: string[] = [];
328→
329→  // For each share recipient, re-wrap all new item keys
330→  for (const share of coveringShares) {
331→    try {
332→      const recipientPubKey = hexToBytes(
333→        share.recipientPublicKey.startsWith('0x')
334→          ? share.recipientPublicKey.slice(2)
335→          : share.recipientPublicKey
336→      );
337→
338→      const wrappedKeys: Array<{
339→        keyType: 'file' | 'folder';
340→        itemId: string;
341→        encryptedKey: string;
342→      }> = [];
343→
344→      for (const item of params.newItems) {
345→        const wrapped = await wrapKey(item.plaintextKey, recipientPubKey);
346→        wrappedKeys.push({
347→          keyType: item.keyType,
348→          itemId: item.itemId,
349→          encryptedKey: bytesToHex(wrapped),
350→        });
351→      }
352→
353→      // Add the wrapped keys to this share via API
354→      await addShareKeys(share.shareId, wrappedKeys);
355→    } catch (err) {
356→      console.warn(
357→        `[share] Failed to re-wrap keys for recipient ${share.recipientPublicKey.slice(0, 10)}...:`,
358→        err
359→      );
360→      failedRecipients.push(share.recipientPublicKey);
361→    }
362→  }
363→
364→  return { failedRecipients };
365→}
