424→
425→/**
426→ * Execute lazy key rotation for a folder.
427→ * Called when a folder modification is about to happen and pending rotations exist.
428→ *
429→ * Protocol:
430→ * 1. Generate new random folderKey
431→ * 2. Re-wrap new folderKey for each REMAINING (non-revoked) active recipient
432→ * 3. Update remaining shares with the new encrypted key
433→ * 4. Hard-delete revoked share records (rotation complete)
434→ * 5. Invalidate share cache
435→ *
436→ * NOTE: The actual folder metadata re-encryption (decrypt with old key, re-encrypt
437→ * with new key, re-publish IPNS) is handled by the caller (folder.service.ts)
438→ * since it has access to the folder's IPNS private key and publishing infrastructure.
439→ *
440→ * @returns The new folderKey for the caller to use
441→ */
442→export async function executeLazyRotation(params: {
443→  folderIpnsName: string;
444→  oldFolderKey: Uint8Array;
445→  ownerPublicKey: Uint8Array;
446→}): Promise<{ newFolderKey: Uint8Array }> {
447→  // 1. Generate new random 32-byte folderKey
448→  const newFolderKey = generateRandomBytes(32);
449→
450→  // 2. Fetch pending rotations and active shares for this folder
451→  const [pendingRotations, activeSentShares] = await Promise.all([
452→    fetchPendingRotations(),
453→    getSentSharesForItem(params.folderIpnsName),
454→  ]);
455→
456→  const revokedForFolder = pendingRotations.filter((r) => r.ipnsName === params.folderIpnsName);
457→  const revokedShareIds = new Set(revokedForFolder.map((r) => r.shareId));
458→
459→  // Active shares that are NOT revoked -- these recipients keep access
460→  const remainingShares = activeSentShares.filter((s) => !revokedShareIds.has(s.shareId));
461→
462→  // 3. Re-wrap new folderKey for each remaining recipient
463→  const reWrapFailures: string[] = [];
464→  for (const share of remainingShares) {
465→    try {
466→      const recipientPubKey = hexToBytes(
467→        share.recipientPublicKey.startsWith('0x')
468→          ? share.recipientPublicKey.slice(2)
469→          : share.recipientPublicKey
470→      );
471→      const wrapped = await wrapKey(newFolderKey, recipientPubKey);
472→      await updateShareKey(share.shareId, bytesToHex(wrapped));
473→    } catch (err) {
474→      console.warn(
475→        `[share] Failed to update share key for remaining recipient ${share.recipientPublicKey.slice(0, 10)}...:`,
476→        err
477→      );
478→      reWrapFailures.push(share.shareId);
479→    }
480→  }
481→
482→  if (reWrapFailures.length > 0) {
483→    newFolderKey.fill(0);
484→    throw new Error(
485→      `Key rotation failed: could not re-wrap key for ${reWrapFailures.length} recipient(s). ` +
486→        'Aborting to prevent inconsistent state.'
487→    );
488→  }
489→
490→  // 4. Hard-delete all revoked shares for this folder
491→  for (const revoked of revokedForFolder) {
492→    try {
493→      await completeShareRotation(revoked.shareId);
494→    } catch (err) {
495→      console.warn(`[share] Failed to complete rotation for share ${revoked.shareId}:`, err);
496→    }
497→  }
498→
499→  // 5. Invalidate the sent shares cache so next check fetches fresh state
500→  useShareStore.getState().setSentShares([]);
501→
502→  return { newFolderKey };
503→}
