 37→type ShareState = {
 38→  receivedShares: ReceivedShare[];
 39→  sentShares: SentShare[];
 40→  isLoadingReceived: boolean;
 41→  isLoadingSent: boolean;
 42→  lastReceivedFetchedAt: number | null;
 43→  lastSentFetchedAt: number | null;
 44→
 45→  // Actions
 46→  setReceivedShares: (shares: ReceivedShare[]) => void;
 47→  setSentShares: (shares: SentShare[]) => void;
 48→  setLoadingReceived: (loading: boolean) => void;
 49→  setLoadingSent: (loading: boolean) => void;
 50→  addSentShare: (share: SentShare) => void;
 51→  removeSentShare: (shareId: string) => void;
 52→  removeReceivedShare: (shareId: string) => void;
 53→  updateSentSharePermission: (shareId: string, permission: 'read' | 'write') => void;
 54→  clearShares: () => void;
