 57→/**
 58→ * Share store for managing sent/received share state.
 59→ *
 60→ * Maintains the in-memory lists of shares the user has
 61→ * sent to others and received from others.
 62→ *
 63→ * Call clearShares() on logout to reset state.
 64→ */
 65→export const useShareStore = create<ShareState>((set) => ({
 66→  // State
 67→  receivedShares: [],
 68→  sentShares: [],
 69→  isLoadingReceived: false,
 70→  isLoadingSent: false,
 71→  lastReceivedFetchedAt: null,
 72→  lastSentFetchedAt: null,
 73→
 74→  // Actions
 75→  setReceivedShares: (shares) =>
 76→    set({ receivedShares: shares, isLoadingReceived: false, lastReceivedFetchedAt: Date.now() }),
 77→
 78→  setSentShares: (shares) =>
 79→    set({ sentShares: shares, isLoadingSent: false, lastSentFetchedAt: Date.now() }),
 80→
 81→  setLoadingReceived: (loading) => set({ isLoadingReceived: loading }),
 82→
 83→  setLoadingSent: (loading) => set({ isLoadingSent: loading }),
 84→
 85→  addSentShare: (share) =>
 86→    set((state) => ({
 87→      sentShares: [...state.sentShares, share],
 88→    })),
 89→
 90→  removeSentShare: (shareId) =>
 91→    set((state) => ({
 92→      sentShares: state.sentShares.filter((s) => s.shareId !== shareId),
 93→    })),
 94→
 95→  removeReceivedShare: (shareId) =>
 96→    set((state) => ({
 97→      receivedShares: state.receivedShares.filter((s) => s.shareId !== shareId),
 98→    })),
 99→
100→  updateSentSharePermission: (shareId, permission) =>
101→    set((state) => ({
102→      sentShares: state.sentShares.map((s) => (s.shareId === shareId ? { ...s, permission } : s)),
103→    })),
104→
105→  clearShares: () =>
106→    set({
107→      receivedShares: [],
108→      sentShares: [],
109→      isLoadingReceived: false,
110→      isLoadingSent: false,
111→      lastReceivedFetchedAt: null,
112→      lastSentFetchedAt: null,
113→    }),
114→}));
