113→/**
114→ * Check if an error is a 403 Forbidden (write access revoked).
115→ */
116→function isForbiddenError(error: unknown): boolean {
117→  if (!error || typeof error !== 'object') return false;
118→  const e = error as Record<string, unknown>;
119→  return e.status === 403;
120→}
