122→/** Parse a 0x-prefixed or bare hex public key string into bytes. */
123→function parsePublicKey(keyHex: string): Uint8Array {
124→  const hex = keyHex.startsWith('0x') ? keyHex.slice(2) : keyHex;
125→  return hexToBytes(hex);
126→}
127→
128→/** Safe base64 encoding that avoids call stack overflow from spread operator. */
129→function uint8ToBase64(bytes: Uint8Array): string {
130→  let binary = '';
131→  for (let i = 0; i < bytes.length; i++) {
132→    binary += String.fromCharCode(bytes[i]);
133→  }
134→  return btoa(binary);
135→}
