451→  /**
452→   * Navigate into a subfolder within a shared folder.
453→   */
454→  const navigateToSubfolder = useCallback(
455→    async (folderId: string, folderName: string) => {
456→      const auth = useAuthStore.getState();
457→      if (!auth.vaultKeypair || !currentShareId) return;
458→
459→      setIsLoading(true);
460→      setError(null);
461→      clearPolling();
462→
463→      try {
464→        // Get re-wrapped keys for this share
465→        const keys = await getShareKeys(currentShareId);
466→
467→        // Find the re-wrapped folder key for this subfolder
468→        const keyRecord = keys.find((k) => k.keyType === 'folder' && k.itemId === folderId);
469→        if (!keyRecord) {
470→          throw new Error('No key available for this subfolder');
471→        }
472→
473→        // Unwrap the subfolder key
474→        const subfolderKey = await unwrapKey(
475→          hexToBytes(keyRecord.encryptedKey),
476→          auth.vaultKeypair.privateKey
477→        );
478→        let subfolderKeyStored = false;
479→
480→        try {
481→          // Find the subfolder entry to get its IPNS name
482→          const folderEntry = folderChildren.find(
483→            (c): c is FolderEntry => c.type === 'folder' && c.id === folderId
484→          );
485→          if (!folderEntry) {
486→            throw new Error('Subfolder not found in current children');
487→          }
488→
489→          // Resolve subfolder IPNS
490→          const resolved = await resolveIpnsRecord(folderEntry.ipnsName);
491→          if (!resolved) {
492→            throw new Error('Could not resolve subfolder IPNS');
493→          }
494→
495→          // Fetch and decrypt subfolder metadata
496→          const encryptedBytes = await fetchFromIpfs(resolved.cid);
497→          const encryptedJson = new TextDecoder().decode(encryptedBytes);
498→          const encrypted: EncryptedFolderMetadata = JSON.parse(encryptedJson);
499→          const metadata = await decryptFolderMetadata(encrypted, subfolderKey);
500→
501→          // Push current state to nav stack
502→          if (folderKey && ipnsName) {
503→            navStackRef.current.push({
504→              folderId: breadcrumbs[breadcrumbs.length - 1]?.id ?? '',
505→              folderName: breadcrumbs[breadcrumbs.length - 1]?.name ?? '',
506→              children: folderChildren,
507→              folderKey,
508→              ipnsName,
509→              sequenceNumber: currentSequenceNumber,
510→            });
511→          }
512→
513→          // Update state + refs
514→          const children = metadata.children ?? [];
515→          const seqNum = BigInt(resolved.sequenceNumber);
516→          setFolderChildren(children);
517→          folderChildrenRef.current = children;
518→          setFolderKey(subfolderKey);
519→          subfolderKeyStored = true;
520→          setBreadcrumbs((prev) => [...prev, { id: folderId, name: folderName }]);
521→          setIpnsName(folderEntry.ipnsName);
522→          setCurrentSequenceNumber(seqNum);
523→          sequenceNumberRef.current = seqNum;
524→
525→          // For write-share recipients: unwrap the subfolder's IPNS private key
526→          // from share_keys (folder-ipns) so write operations work at any depth.
527→          if (permission === 'write' && currentShareId) {
528→            zeroIpnsKey(); // Zero parent key before replacing
529→            let restored = false;
530→            try {
531→              const subKeys = await getShareKeys(currentShareId);
532→              const ipnsKeyRecord = subKeys.find(
533→                (k) => k.keyType === 'folder-ipns' && k.itemId === folderId
534→              );
535→              if (ipnsKeyRecord) {
536→                const ipnsPrivKey = await unwrapKey(
537→                  hexToBytes(ipnsKeyRecord.encryptedKey),
538→                  auth.vaultKeypair.privateKey
539→                );
540→                ipnsPrivateKeyRef.current = ipnsPrivKey;
541→                restored = true;
542→              }
543→            } catch {
544→              // Couldn't get subfolder IPNS key from share_keys
545→            }
546→            if (!restored) {
547→              // No subfolder IPNS key available — drop to read-only for this subfolder
548→              setPermission('read');
549→            }
550→          }
551→        } finally {
552→          if (!subfolderKeyStored) subfolderKey.fill(0);
553→        }
554→      } catch (err) {
555→        console.error('Failed to navigate to subfolder:', err);
556→        setError('Failed to open subfolder');
557→      } finally {
558→        setIsLoading(false);
559→      }
560→    },
561→    [
562→      currentShareId,
563→      folderChildren,
564→      folderKey,
565→      breadcrumbs,
566→      getShareKeys,
567→      ipnsName,
568→      currentSequenceNumber,
569→      clearPolling,
570→      permission,
571→      zeroIpnsKey,
572→    ]
573→  );
