575→  /**
576→   * Navigate back to the top-level shared list.
577→   * Zeroes all decrypted folder keys from memory before clearing state.
578→   */
579→  const navigateToRoot = useCallback(() => {
580→    // Zero current folder key
581→    if (folderKey) folderKey.fill(0);
582→    // Zero all nav stack folder keys
583→    for (const entry of navStackRef.current) {
584→      entry.folderKey.fill(0);
585→    }
586→    // Zero IPNS private key
587→    zeroIpnsKey();
588→    // Clear polling
589→    clearPolling();
590→    setCurrentView('list');
591→    setCurrentShareId(null);
592→    setFolderChildren([]);
593→    setFolderKey(null);
594→    setBreadcrumbs([]);
595→    setPermission(null);
596→    setIpnsName(null);
597→    setCurrentSequenceNumber(null);
598→    navStackRef.current = [];
599→    setError(null);

 600→  }, [folderKey, zeroIpnsKey, clearPolling]);
 601→
 602→  /**
 603→   * Navigate up one level.
 604→   */
 605→  /**
 606→   * Restore the correct IPNS private key for the current depth.
 607→   * Root level: unwrap from share record. Subfolder level: unwrap from folder-ipns share_key.
 608→   */
 609→  const restoreIpnsKeyForDepth = useCallback(
 610→    async (targetFolderId?: string) => {
 611→      if (!currentShareId) return;
 612→      const shareItem = sharedItems.find((s) => s.share.shareId === currentShareId);
 613→      const share = shareItem?.share;
 614→      if (share?.permission !== 'write') return;
 615→
 616→      zeroIpnsKey();
 617→      const auth = useAuthStore.getState();
 618→      if (!auth.vaultKeypair) return;
 619→
 620→      try {
 621→        if (!targetFolderId && share.encryptedIpnsKey) {
 622→          // Root share level — unwrap from share record
 623→          const ipnsPrivKey = await unwrapKey(
 624→            hexToBytes(share.encryptedIpnsKey),
 625→            auth.vaultKeypair.privateKey
 626→          );
 627→          ipnsPrivateKeyRef.current = ipnsPrivKey;
 628→          setPermission('write');
 629→        } else if (targetFolderId) {
 630→          // Subfolder level — unwrap from folder-ipns share_key
 631→          const keys = await getShareKeys(currentShareId);
 632→          const ipnsKeyRecord = keys.find(
 633→            (k) => k.keyType === 'folder-ipns' && k.itemId === targetFolderId
 634→          );
 635→          if (ipnsKeyRecord) {
 636→            const ipnsPrivKey = await unwrapKey(
 637→              hexToBytes(ipnsKeyRecord.encryptedKey),
 638→              auth.vaultKeypair.privateKey
 639→            );
 640→            ipnsPrivateKeyRef.current = ipnsPrivKey;
 641→            setPermission('write');
 642→          } else {
 643→            setPermission('read');
 644→          }
 645→        }
 646→      } catch {
 647→        // Couldn't restore — stay read-only
 648→      }
 649→    },
 650→    [currentShareId, getShareKeys, sharedItems, zeroIpnsKey]
 651→  );
 652→
 653→  const navigateUp = useCallback(async () => {
 654→    if (navStackRef.current.length > 0) {
 655→      // Zero current folder key before replacing
 656→      if (folderKey) folderKey.fill(0);
 657→      // Pop from nav stack
 658→      const prev = navStackRef.current.pop()!;
 659→      setFolderChildren(prev.children);
 660→      folderChildrenRef.current = prev.children;
 661→      setFolderKey(prev.folderKey);
 662→      setBreadcrumbs((crumbs) => crumbs.slice(0, -1));
 663→      setIpnsName(prev.ipnsName);
 664→      setCurrentSequenceNumber(prev.sequenceNumber);
 665→      sequenceNumberRef.current = prev.sequenceNumber;
 666→
 667→      // Restore IPNS key: root level (no stack) or subfolder (top of remaining stack)
 668→      if (navStackRef.current.length === 0) {
 669→        await restoreIpnsKeyForDepth(); // root level
 670→      } else {
 671→        await restoreIpnsKeyForDepth(prev.folderId);
 672→      }
 673→    } else if (currentView === 'folder' || currentView === 'file') {
 674→      // Back to top-level list
 675→      navigateToRoot();
 676→    }
 677→  }, [currentView, folderKey, navigateToRoot, restoreIpnsKeyForDepth]);
 678→
 679→  /**
 680→   * Navigate directly to a breadcrumb level, zeroing all intermediate keys.
 681→   * More efficient than calling navigateUp() in a loop.
 682→   */
 683→  const navigateToBreadcrumb = useCallback(
 684→    async (crumbIndex: number) => {
 685→      const popsNeeded = breadcrumbs.length - 1 - crumbIndex;
 686→      if (popsNeeded <= 0) return;
 687→      // Zero the current folder key
 688→      if (folderKey) folderKey.fill(0);
 689→      // Zero and discard all intermediate keys
 690→      for (let i = 0; i < popsNeeded - 1; i++) {
 691→        const entry = navStackRef.current.pop();
 692→        if (entry) entry.folderKey.fill(0);
 693→      }
 694→      // Restore the target level
 695→      const target = navStackRef.current.pop();
 696→      if (target) {
 697→        setFolderChildren(target.children);
 698→        folderChildrenRef.current = target.children;
 699→        setFolderKey(target.folderKey);
 700→        setBreadcrumbs((crumbs) => crumbs.slice(0, crumbIndex + 1));
 701→        setIpnsName(target.ipnsName);
 702→        setCurrentSequenceNumber(target.sequenceNumber);
 703→        sequenceNumberRef.current = target.sequenceNumber;
 704→
 705→        // Restore IPNS key for the target depth
 706→        if (navStackRef.current.length === 0) {
 707→          await restoreIpnsKeyForDepth(); // root level
 708→        } else {
 709→          await restoreIpnsKeyForDepth(target.folderId);
 710→        }
 711→      }
 712→    },
 713→    [breadcrumbs, folderKey, restoreIpnsKeyForDepth]
 714→  );
