 716→  /**
 717→   * Download a shared file from within a shared folder.
 718→   * Uses re-wrapped file keys from share_keys.
 719→   */
 720→  const downloadSharedFile = useCallback(
 721→    async (item: FilePointer) => {
 722→      const auth = useAuthStore.getState();
 723→      if (!auth.vaultKeypair || !currentShareId || !folderKey) return;
 724→
 725→      const downloadStore = useDownloadStore.getState();
 726→
 727→      try {
 728→        downloadStore.startDownload(item.name);
 729→
 730→        // Get share keys for file key lookup
 731→        const keys = await getShareKeys(currentShareId);
 732→
 733→        // First resolve the file metadata using the parent folder key
 734→        const resolved = await resolveIpnsRecord(item.fileMetaIpnsName);
 735→        if (!resolved) {
 736→          throw new Error('File metadata IPNS not found');
 737→        }
 738→
 739→        const encryptedBytes = await fetchFromIpfs(resolved.cid);
 740→        const encryptedJson = new TextDecoder().decode(encryptedBytes);
 741→        const encrypted: EncryptedFileMetadata = JSON.parse(encryptedJson);
 742→        const fileMeta = await decryptFileMetadata(encrypted, folderKey);
 743→
 744→        // Look for a re-wrapped file key in share_keys,
 745→        // falling back to fileKeyEncrypted from metadata (for files uploaded by current user)
 746→        const fileKeyRecord = keys.find((k) => k.keyType === 'file' && k.itemId === item.id);
 747→        if (!fileKeyRecord) {
 748→          throw new Error('File key not available — the folder owner may need to re-share');
 749→        }
 750→        const wrappedKey = fileKeyRecord.encryptedKey;
 751→
 752→        // downloadFile handles unwrapping internally via wrappedKey + privateKey
 753→        const plaintext = await downloadFile(
 754→          {
 755→            cid: fileMeta.cid,
 756→            iv: fileMeta.fileIv,
 757→            wrappedKey,
 758→            originalName: item.name,
 759→            encryptionMode: fileMeta.encryptionMode,
 760→          },
 761→          auth.vaultKeypair.privateKey
 762→        );
 763→
 764→        downloadStore.setDecrypting();
 765→        triggerBrowserDownload(plaintext, item.name);
 766→        downloadStore.setSuccess();
 767→      } catch (err) {
 768→        const message = (err as Error).message || 'Download failed';
 769→        downloadStore.setError(message);
 770→        console.error('Shared file download failed:', err);
 771→      }
 772→    },
 773→    [currentShareId, folderKey, getShareKeys]
 774→  );
