 790→  // -------------------------------------------------------------------------
 791→  // Write operation helpers for write-share recipients
 792→  // -------------------------------------------------------------------------
 793→
 794→  /**
 795→   * Re-sync the current shared folder for conflict retry.
 796→   * Updates folderChildren and currentSequenceNumber in-place.
 797→   */
 798→  const resyncSharedFolder = useCallback(async () => {
 799→    if (!ipnsName || !folderKey) return;
 800→    await refreshFolderContents(ipnsName, folderKey);
 801→  }, [ipnsName, folderKey, refreshFolderContents]);
 802→
 803→  /**
 804→   * Publish updated folder metadata to IPNS using the write-share IPNS key.
 805→   * Returns the new sequence number on success.
 806→   */
 807→  const publishSharedFolderMetadata = useCallback(
 808→    async (
 809→      children: FolderChild[],
 810→      currentFolderKey: Uint8Array,
 811→      folderIpnsName: string,
 812→      ipnsPrivKey: Uint8Array,
 813→      seqNum: bigint
 814→    ): Promise<bigint> => {
 815→      // 1. Create folder metadata
 816→      const metadata: FolderMetadata = {
 817→        version: 'v2',
 818→        children,
 819→      };
 820→
 821→      // 2. Encrypt metadata with folder key
 822→      const encrypted = await encryptFolderMetadata(metadata, currentFolderKey);
 823→
 824→      // 3. Upload to IPFS via backend relay
 825→      const blob = new Blob([JSON.stringify(encrypted)], {
 826→        type: 'application/json',
 827→      });
 828→      const { cid } = await addToIpfs(blob);
 829→
 830→      // 4. Publish IPNS record
 831→      const newSeq = seqNum + 1n;
 832→      await createAndPublishIpnsRecord({
 833→        ipnsPrivateKey: ipnsPrivKey,
 834→        ipnsName: folderIpnsName,
 835→        metadataCid: cid,
 836→        sequenceNumber: newSeq,
 837→        expectedSequenceNumber: seqNum.toString(),
 838→      });
 839→
 840→      return newSeq;
 841→    },
 842→    []
 843→  );
 844→
 845→  /**
 846→   * Wrap a write operation with 403 revocation detection.
 847→   * If 403 is received, transitions to read-only silently.
 848→   */
 849→  const withRevocationGuard = useCallback(
 850→    async <T>(operation: () => Promise<T>): Promise<T> => {
 851→      try {
 852→        return await operation();
 853→      } catch (err) {
 854→        if (isForbiddenError(err)) {
 855→          handleRevocation(true);
 856→          throw new Error('> write access revoked -- folder is now read-only');
 857→        }
 858→        throw err;
 859→      }
 860→    },
 861→    [handleRevocation]
 862→  );
 863→
 864→  /**
 865→   * Upload a file to the currently-viewed write-shared folder.
 866→   * Creates a proper per-file IPNS metadata record (same as owner uploads).
 867→   */
 868→  const uploadFileHandler = useCallback(
 869→    async (file: File) => {
 870→      const currentIpnsKey = ipnsPrivateKeyRef.current;
 871→      const currentFolderKey = folderKey;
 872→      const currentIpnsName = ipnsName;
 873→      const seqNum = currentSequenceNumber;
 874→
 875→      if (!currentIpnsKey || !currentFolderKey || !currentIpnsName || seqNum === null) {
 876→        setError('Write access not available');
 877→        return;
 878→      }
 879→
 880→      const auth = useAuthStore.getState();
 881→      if (!auth.vaultKeypair) {
 882→        setError('No keypair available');
 883→        return;
 884→      }
 885→
 886→      // Get the owner's public key from the share record
 887→      const shareItem = sharedItems.find((s) => s.share.shareId === currentShareId);
 888→      if (!shareItem) {
 889→        setError('Share not found');
 890→        return;
 891→      }
 892→      const ownerPublicKey = parsePublicKey(shareItem.share.sharerPublicKey);
 893→
 894→      setIsLoading(true);
 895→      setError(null);
 896→
 897→      try {
 898→        await withRevocationGuard(async () => {
 899→          // Read file content
 900→          const data = new Uint8Array(await file.arrayBuffer());
 901→
 902→          // Encrypt file content with AES-256-GCM
 903→          const { encryptAesGcm, generateFileKey, generateIv } = await import('@cipherbox/crypto');
 904→
 905→          const fileKey = generateFileKey();
 906→          const iv = generateIv();
 907→
 908→          try {
 909→            const ciphertext = await encryptAesGcm(data, fileKey, iv);
 910→
 911→            // Upload encrypted content to IPFS
 912→            const fileBlob = new Blob([new Uint8Array(ciphertext)], {
 913→              type: 'application/octet-stream',
 914→            });
 915→            const { cid: contentCid } = await addToIpfs(fileBlob);
 916→
 917→            // Wrap file key with owner's public key for file metadata
 918→            const ownerWrappedKey = await wrapKey(fileKey, ownerPublicKey);
 919→            const fileKeyEncrypted = bytesToHex(ownerWrappedKey);
 920→
 921→            // Generate IPNS keypair for this file's metadata record
 922→            // Inline instead of using createFileMetadata so we can wrap with both keys
 923→            const fileId = crypto.randomUUID();
 924→            const mimeType = file.type || 'application/octet-stream';
 925→            const ipnsKeypair = await generateFileIpnsKeypair();
 926→
 927→            try {
 928→              // Wrap IPNS private key with owner's key (stored in FilePointer — owner can update)
 929→              const ownerWrappedIpnsKey = await wrapKey(ipnsKeypair.privateKey, ownerPublicKey);
 930→              const ipnsPrivateKeyEncrypted = bytesToHex(ownerWrappedIpnsKey);
 931→
 932→              // Wrap IPNS private key with recipient's key (stored in share_keys — recipient can update)
 933→              const recipientWrappedIpnsKey = await wrapKey(
 934→                ipnsKeypair.privateKey,
 935→                auth.vaultKeypair!.publicKey
 936→              );
 937→
 938→              // Create and encrypt file metadata
 939→              const now = Date.now();
 940→              const fileMeta: FileMetadata = {
 941→                version: 'v1',
 942→                cid: contentCid,
 943→                fileKeyEncrypted,
 944→                fileIv: bytesToHex(iv),
 945→                size: data.length,
 946→                mimeType,
 947→                encryptionMode: 'GCM',
 948→                createdAt: now,
 949→                modifiedAt: now,
 950→              };
 951→              const encrypted = await encryptFileMetadata(fileMeta, currentFolderKey);
 952→
 953→              // Upload encrypted metadata to IPFS
 954→              const metaBlob = new Blob([JSON.stringify(encrypted)], { type: 'application/json' });
 955→              const { cid: metadataCid } = await addToIpfs(metaBlob);
 956→
 957→              // Create and publish IPNS record
 958→              const ipnsLifetimeMs = 24 * 60 * 60 * 1000;
 959→              const record = await createIpnsRecord(
 960→                ipnsKeypair.privateKey,
 961→                `/ipfs/${metadataCid}`,
 962→                1n,
 963→                ipnsLifetimeMs
 964→              );
 965→              const recordBytes = marshalIpnsRecord(record);
 966→              const recordBase64 = uint8ToBase64(recordBytes);
 967→
 968→              await batchPublishIpnsRecords([
 969→                {
 970→                  ipnsName: ipnsKeypair.ipnsName,
 971→                  recordBase64,
 972→                  metadataCid,
 973→                  recordType: 'file' as const,
 974→                },
 975→              ]);
 976→
 977→              // Create FilePointer with owner-wrapped IPNS key
 978→              const filePointer: FilePointer = {
 979→                type: 'file',
 980→                id: fileId,
 981→                name: file.name,
 982→                fileMetaIpnsName: ipnsKeypair.ipnsName,
 983→                ipnsPrivateKeyEncrypted,
 984→                createdAt: now,
 985→                modifiedAt: now,
 986→              };
 987→
 988→              // Add file to folder metadata with conflict retry (C-01: read from refs)
 989→              await withConflictRetry(
 990→                async () => {
 991→                  const freshChildren = [...folderChildrenRef.current, filePointer];
 992→                  const seqNum = sequenceNumberRef.current ?? 0n;
 993→                  const newSeq = await publishSharedFolderMetadata(
 994→                    freshChildren,
 995→                    currentFolderKey,
 996→                    currentIpnsName,
 997→                    currentIpnsKey,
 998→                    seqNum
 999→                  );
