1276→  /**
1277→   * Update a file's content in the currently-viewed write-shared folder.
1278→   * Creates new encrypted content, updates the file's IPNS metadata record,
1279→   * and refreshes the recipient's share_key.
1280→   */
1281→  const updateSharedFileHandler = useCallback(
1282→    async (item: FilePointer, newContent: Uint8Array): Promise<void> => {
1283→      const currentFolderKey = folderKey;
1284→
1285→      if (!currentFolderKey) {
1286→        throw new Error('Folder key not available');
1287→      }
1288→
1289→      const auth = useAuthStore.getState();
1290→      if (!auth.vaultKeypair) {
1291→        throw new Error('No keypair available');
1292→      }
1293→
1294→      // Get the owner's public key from the share record
1295→      const shareItem = sharedItems.find((s) => s.share.shareId === currentShareId);
1296→      if (!shareItem) {
1297→        throw new Error('Share not found');
1298→      }
1299→      const ownerPublicKey = parsePublicKey(shareItem.share.sharerPublicKey);
1300→
1301→      // 1. Encrypt new content with AES-256-GCM
1302→      const { encryptAesGcm, generateFileKey, generateIv } = await import('@cipherbox/crypto');
1303→      const fileKey = generateFileKey();
1304→      const iv = generateIv();
1305→
1306→      try {
1307→        const ciphertext = await encryptAesGcm(newContent, fileKey, iv);
1308→
1309→        // 2. Upload encrypted content to IPFS
1310→        const fileBlob = new Blob([new Uint8Array(ciphertext)], {
1311→          type: 'application/octet-stream',
1312→        });
1313→        const { cid: contentCid } = await addToIpfs(fileBlob);
1314→
1315→        // 3. Wrap file key with owner's public key
1316→        const ownerWrappedKey = await wrapKey(fileKey, ownerPublicKey);
1317→        const fileKeyEncrypted = bytesToHex(ownerWrappedKey);
1318→
1319→        // 4. Get the file's IPNS private key
1320→        // For recipient-uploaded files: wrapped with recipient's key in share_keys (file-ipns)
1321→        // For owner-uploaded files: wrapped with owner's key in FilePointer (try unwrap)
1322→        const { updateFileMetadata } = await import('../services/file-metadata.service');
1323→
1324→        let ipnsPrivKey: Uint8Array;
1325→        const keys = await fetchShareKeys(currentShareId!);
1326→        const ipnsKeyRecord = keys.find((k) => k.keyType === 'file-ipns' && k.itemId === item.id);
1327→
1328→        if (ipnsKeyRecord) {
1329→          // Recipient-uploaded file: unwrap from share_keys
1330→          ipnsPrivKey = await unwrapKey(
1331→            hexToBytes(ipnsKeyRecord.encryptedKey),
1332→            auth.vaultKeypair.privateKey
1333→          );
1334→        } else if (item.ipnsPrivateKeyEncrypted) {
1335→          // Owner-uploaded file: try unwrapping from FilePointer
1336→          try {
1337→            ipnsPrivKey = await unwrapKey(
1338→              hexToBytes(item.ipnsPrivateKeyEncrypted),
1339→              auth.vaultKeypair.privateKey
1340→            );
1341→          } catch {
1342→            throw new Error('Cannot update: file IPNS key not accessible');
1343→          }
1344→        } else {
1345→          throw new Error('Cannot update: no IPNS key available');
1346→        }
1347→
1348→        try {
1349→          // 5. Resolve current file metadata and update
1350→          const { resolveFileMetadata } = await import('../services/file-metadata.service');
1351→          const { metadata: currentMeta } = await resolveFileMetadata(
1352→            item.fileMetaIpnsName,
1353→            currentFolderKey
1354→          );
1355→
1356→          const { ipnsRecord } = await updateFileMetadata({
1357→            fileIpnsPrivateKey: ipnsPrivKey,
1358→            fileMetaIpnsName: item.fileMetaIpnsName,
1359→            folderKey: currentFolderKey,
1360→            currentMetadata: currentMeta,
1361→            updates: {
1362→              cid: contentCid,
1363→              fileKeyEncrypted,
1364→              fileIv: bytesToHex(iv),
1365→              size: newContent.length,
1366→              encryptionMode: 'GCM',
1367→            },
1368→            createVersion: false,
1369→          });
1370→
1371→          // 6. Publish updated file IPNS record
1372→          await batchPublishIpnsRecords([{ ...ipnsRecord, recordType: 'file' as const }]);
1373→
1374→          // 7. Update share_key for recipient so they can re-read the file
1375→          const recipientWrappedKey = await wrapKey(fileKey, auth.vaultKeypair!.publicKey);
1376→          await addShareKeys(currentShareId!, [
1377→            { keyType: 'file', itemId: item.id, encryptedKey: bytesToHex(recipientWrappedKey) },
1378→          ])
1379→            .then(() => {
1380→              shareKeysCache.current.delete(currentShareId!);
1381→            })
1382→            .catch((err) => {
1383→              console.warn('[share] Failed to update share_key after file edit:', err);
1384→            });
1385→        } finally {
1386→          ipnsPrivKey.fill(0);
1387→        }
1388→      } finally {
1389→        fileKey.fill(0);
1390→      }
1391→    },
1392→    [folderKey, currentShareId, sharedItems]
1393→  );
