1467→  useEffect(() => {
1468→    // Only poll when viewing a write-shared folder
1469→    if (currentView !== 'folder' || permission !== 'write' || !ipnsName || !folderKey) {
1470→      clearPolling();
1471→      return;
1472→    }
1473→
1474→    // Start 30s polling
1475→    const currentIpnsName = ipnsName;
1476→    const currentFolderKey = folderKey;
1477→
1478→    pollIntervalRef.current = setInterval(async () => {
1479→      try {
1480→        // Re-fetch received shares from API to detect permission changes
1481→        const freshShares = await fetchReceivedShares(100, 0);
1482→        const currentShare = freshShares.shares.find((s) => s.shareId === currentShareId);
1483→
1484→        // Check for silent revocation or permission downgrade
1485→        if (!currentShare || currentShare.permission !== 'write') {
1486→          useShareStore.getState().setReceivedShares(freshShares.shares);
1487→          handleRevocation(false);
1488→          clearPolling();
1489→          return;
1490→        }
1491→
1492→        // Refresh folder contents
1493→        await refreshFolderContents(currentIpnsName, currentFolderKey);
1494→      } catch {
1495→        // Silent failure during polling -- don't disrupt the UI
1496→      }
1497→    }, 30000);
1498→
1499→    return () => {
1500→      clearPolling();
1501→    };
1502→  }, [
