109→  /**
110→   * Re-wrap keys for share recipients after adding items to a folder.
111→   *
112→   * Queries the share callbacks for active shares covering the folder,
113→   * then wraps each new item's plaintext key for each recipient.
114→   * Failures are logged but do not propagate (re-wrapping is best-effort).
115→   */
116→  private async reWrapNewItems(
117→    folderIpnsName: string,
118→    items: Array<{ keyType: 'file' | 'folder'; itemId: string; plaintextKey: Uint8Array }>
119→  ): Promise<void> {
120→    const callbacks = this.config.shareCallbacks;
121→    if (!callbacks) return;
122→
123→    const coveringShares = await callbacks.getCoveringShares(folderIpnsName);
124→    if (coveringShares.length === 0) return;
125→
126→    const { failedRecipients } = await shareOps.reWrapForRecipients({
127→      coveringShares,
128→      newItems: items,
129→      addShareKeysFn: callbacks.addShareKeys,
130→    });
131→
132→    if (failedRecipients.length > 0) {
133→      console.warn(
134→        `[SDK] Re-wrapping failed for ${failedRecipients.length} recipient(s):`,
135→        failedRecipients.map((k) => k.slice(0, 10) + '...')
136→      );
137→      this.emitter.emit({
138→        type: 'share:reWrapFailed',
139→        folderIpnsName,
140→        failedRecipients,
141→      } as SdkEvent);
142→    }
143→  }
