145→  /**
146→   * Destroy the client, clearing all sensitive state.
147→   * After calling destroy(), the client instance should not be reused.
148→   */
149→  destroy(): void {
150→    this.folderTree.clear();
151→    this.keyCache.clear();
152→    this.emitter.removeAll();
153→    // Zero internal key copies (defense-in-depth; JS GC may retain copies)
154→    // Only zeroes our copies, not the caller-provided buffers
155→    this.internalVaultKeypair.privateKey.fill(0);
156→    this.internalVaultKeypair.publicKey.fill(0);
157→    this.internalRootFolderKey.fill(0);
158→    this.binState = null;
159→  }
