import { describe, it, expect, vi, beforeEach, type Mock } from 'vitest';
import type { FolderChild, FolderEntry, FilePointer } from '@cipherbox/core';

// ---- Mocks ----

vi.mock('@cipherbox/crypto', () => ({
  encryptAesGcm: vi.fn().mockResolvedValue(new Uint8Array([0xde, 0xad])),
  generateFileKey: vi.fn().mockReturnValue(new Uint8Array(32).fill(0x11)),
  generateIv: vi.fn().mockReturnValue(new Uint8Array(12).fill(0x22)),
  wrapKey: vi.fn().mockResolvedValue(new Uint8Array([0xaa, 0xbb, 0xcc])),
  bytesToHex: vi.fn().mockReturnValue('aabbcc'),
  hexToBytes: vi.fn().mockReturnValue(new Uint8Array(33).fill(9)),
  generateRandomBytes: vi.fn().mockReturnValue(new Uint8Array(32).fill(0x33)),
  generateEd25519Keypair: vi.fn().mockResolvedValue({
    publicKey: new Uint8Array(32).fill(0x44),
    privateKey: new Uint8Array(64).fill(0x55),
  }),
  deriveIpnsName: vi.fn().mockResolvedValue('k51subfolder'),
}));

vi.mock('@cipherbox/core', async () => {
  const actual = await vi.importActual<typeof import('@cipherbox/core')>('@cipherbox/core');
  return {
    ...actual,
    generateFileIpnsKeypair: vi.fn().mockResolvedValue({
      ipnsName: 'k51fileipns',
      publicKey: new Uint8Array(32).fill(0x66),
      privateKey: new Uint8Array(64).fill(0x77),
    }),
    encryptFolderMetadata: vi.fn().mockResolvedValue({ iv: 'mock-iv', data: 'mock-data' }),
    encryptFileMetadata: vi.fn().mockResolvedValue({ iv: 'mock-iv', data: 'mock-data' }),
  };
});

vi.mock('@cipherbox/sdk-core', () => ({
  updateFolderMetadataAndPublish: vi.fn().mockResolvedValue({
    cid: 'QmUpdated',
    newSequenceNumber: 2n,
  }),
  addToIpfs: vi.fn().mockResolvedValue({ cid: 'QmUploaded', size: 100, recorded: true }),
  batchPublishIpnsRecords: vi.fn().mockResolvedValue({ totalSucceeded: 1, totalFailed: 0 }),
  createAndPublishIpnsRecord: vi.fn().mockResolvedValue({ success: true, sequenceNumber: 1n }),
  resolveFileMetadata: vi.fn().mockResolvedValue({
    metadata: {
      version: 'v1',
      cid: 'QmOldFile',
      fileKeyEncrypted: 'oldkey',
      fileIv: 'oldiv',
      size: 50,
      mimeType: 'text/plain',
      encryptionMode: 'GCM',
      createdAt: 1000,
      modifiedAt: 1000,
    },
    metadataCid: 'QmOldMeta',
  }),
  updateFileMetadata: vi.fn().mockResolvedValue({
    ipnsRecord: {
      ipnsName: 'k51fileipns',
      recordBase64: 'mockbase64',
      metadataCid: 'QmNewMeta',
    },
    prunedCids: [],
  }),
}));

// ---- Imports under test (after mocks) ----

import {
  uploadToSharedFolder,
  createSharedSubfolder,
  renameInSharedFolder,
  deleteFromSharedFolder,
  updateSharedFile,
  updateSharePermission,
  type SharedWriteContext,
} from '../share/shared-write';

import { updateFolderMetadataAndPublish, addToIpfs, batchPublishIpnsRecords, createAndPublishIpnsRecord } from '@cipherbox/sdk-core';
import { wrapKey, encryptAesGcm } from '@cipherbox/crypto';

// ---- Helpers ----

function makeSWCtx(overrides?: Partial<SharedWriteContext>): SharedWriteContext {
  return {
    ctx: {
      apiUrl: 'http://localhost:3000',
      getAccessToken: async () => 'token',
    },
    folderKey: new Uint8Array(32).fill(1),
    ipnsPrivateKey: new Uint8Array(64).fill(2),
    ipnsName: 'k51folder',
    sequenceNumber: 1n,
    children: [],
    ownerPublicKey: new Uint8Array(33).fill(3),
    recipientPublicKey: new Uint8Array(33).fill(4),
    shareId: 'share-123',
    addShareKeysFn: vi.fn().mockResolvedValue(undefined),
    ...overrides,
  };
}

// ---- Tests ----

describe('shared-write operations', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  // ---------- uploadToSharedFolder ----------

  describe('uploadToSharedFolder', () => {
    it('encrypts file, uploads to IPFS, creates file metadata IPNS, updates folder, and calls addShareKeysFn', async () => {
      const swCtx = makeSWCtx();
      const result = await uploadToSharedFolder(swCtx, {
        data: new Uint8Array([1, 2, 3]),
        fileName: 'test.txt',
        mimeType: 'text/plain',
      });

      // Encryption was called
      expect(encryptAesGcm).toHaveBeenCalled();

      // Uploaded encrypted content to IPFS
      expect(addToIpfs).toHaveBeenCalled();

      // File IPNS published via batch
      expect(batchPublishIpnsRecords).toHaveBeenCalled();

      // Parent folder updated
      expect(updateFolderMetadataAndPublish).toHaveBeenCalled();

      // Result contains FilePointer and updated state
      expect(result.filePointer).toBeDefined();
      expect(result.filePointer.type).toBe('file');
      expect(result.filePointer.name).toBe('test.txt');
      expect(result.updatedChildren).toHaveLength(1);
      expect(result.newSequenceNumber).toBe(2n);
    });

    it('wraps keys with both owner and recipient public keys', async () => {
      const swCtx = makeSWCtx();
      await uploadToSharedFolder(swCtx, {
        data: new Uint8Array([1]),
        fileName: 'test.txt',
      });

      // wrapKey is called multiple times: fileKey for owner, IPNS key for owner,
      // IPNS key for recipient, fileKey for recipient
      expect(wrapKey).toHaveBeenCalledTimes(4);
    });

    it('calls addShareKeysFn with file and file-ipns keys', async () => {
      const addFn = vi.fn().mockResolvedValue(undefined);
      const swCtx = makeSWCtx({ addShareKeysFn: addFn });

      await uploadToSharedFolder(swCtx, {
        data: new Uint8Array([1]),
        fileName: 'test.txt',
      });

      expect(addFn).toHaveBeenCalledWith('share-123', expect.arrayContaining([
        expect.objectContaining({ keyType: 'file' }),
        expect.objectContaining({ keyType: 'file-ipns' }),
      ]));
    });

    it('warns but does not throw when addShareKeysFn fails', async () => {
      const addFn = vi.fn().mockRejectedValue(new Error('API error'));
      const consoleWarn = vi.spyOn(console, 'warn').mockImplementation(() => {});
      const swCtx = makeSWCtx({ addShareKeysFn: addFn });

      // Should not throw
      const result = await uploadToSharedFolder(swCtx, {
        data: new Uint8Array([1]),
        fileName: 'test.txt',
      });

      expect(result.filePointer).toBeDefined();
      expect(consoleWarn).toHaveBeenCalled();
      consoleWarn.mockRestore();
    });
  });

  // ---------- createSharedSubfolder ----------

  describe('createSharedSubfolder', () => {
    it('creates subfolder IPNS, updates parent, and calls addShareKeysFn', async () => {
      const swCtx = makeSWCtx();
      const result = await createSharedSubfolder(swCtx, { name: 'New Folder' });

      // Subfolder IPNS published
      expect(createAndPublishIpnsRecord).toHaveBeenCalled();

      // Parent folder updated
      expect(updateFolderMetadataAndPublish).toHaveBeenCalled();

      // Result contains FolderEntry
      expect(result.folderEntry).toBeDefined();
      expect(result.folderEntry.type).toBe('folder');
      expect(result.folderEntry.name).toBe('New Folder');
      expect(result.updatedChildren).toHaveLength(1);
      expect(result.newSequenceNumber).toBe(2n);
    });

    it('calls addShareKeysFn with folder and folder-ipns keys', async () => {
      const addFn = vi.fn().mockResolvedValue(undefined);
      const swCtx = makeSWCtx({ addShareKeysFn: addFn });

      await createSharedSubfolder(swCtx, { name: 'Sub' });

      expect(addFn).toHaveBeenCalledWith('share-123', expect.arrayContaining([
        expect.objectContaining({ keyType: 'folder' }),
        expect.objectContaining({ keyType: 'folder-ipns' }),
      ]));
    });

    it('warns but does not throw when addShareKeysFn fails', async () => {
      const addFn = vi.fn().mockRejectedValue(new Error('API error'));
      const consoleWarn = vi.spyOn(console, 'warn').mockImplementation(() => {});
      const swCtx = makeSWCtx({ addShareKeysFn: addFn });

      const result = await createSharedSubfolder(swCtx, { name: 'Sub' });

      expect(result.folderEntry).toBeDefined();
      expect(consoleWarn).toHaveBeenCalled();
      consoleWarn.mockRestore();
    });
  });

  // ---------- renameInSharedFolder ----------

  describe('renameInSharedFolder', () => {
    it('updates the item name and republishes folder', async () => {
      const existingChild: FilePointer = {
        type: 'file',
        id: 'f1',
        name: 'old.txt',
        fileMetaIpnsName: 'k51file',
        ipnsPrivateKeyEncrypted: 'enc',
        createdAt: 1000,
        modifiedAt: 1000,
      };
      const swCtx = makeSWCtx({ children: [existingChild] });

      const result = await renameInSharedFolder(swCtx, {
        itemId: 'f1',
        newName: 'new.txt',
      });

      // Folder was re-published
      expect(updateFolderMetadataAndPublish).toHaveBeenCalled();

      // Updated children have new name
      const call = (updateFolderMetadataAndPublish as Mock).mock.calls[0][0];
      const updated = call.children.find((c: FolderChild) => c.id === 'f1');
      expect(updated.name).toBe('new.txt');
      expect(updated.modifiedAt).toBeGreaterThan(1000);

      expect(result.updatedChildren).toHaveLength(1);
      expect(result.newSequenceNumber).toBe(2n);
    });
  });

  // ---------- deleteFromSharedFolder ----------

  describe('deleteFromSharedFolder', () => {
    it('removes the item from children and republishes folder', async () => {
      const existingChild: FilePointer = {
        type: 'file',
        id: 'f1',
        name: 'doomed.txt',
        fileMetaIpnsName: 'k51file',
        ipnsPrivateKeyEncrypted: 'enc',
        createdAt: 1000,
        modifiedAt: 1000,
      };
      const swCtx = makeSWCtx({ children: [existingChild] });

      const result = await deleteFromSharedFolder(swCtx, { itemId: 'f1' });

      // Folder was re-published with empty children
      expect(updateFolderMetadataAndPublish).toHaveBeenCalled();
      const call = (updateFolderMetadataAndPublish as Mock).mock.calls[0][0];
      expect(call.children).toHaveLength(0);

      expect(result.updatedChildren).toHaveLength(0);
      expect(result.newSequenceNumber).toBe(2n);
    });
  });

  // ---------- updateSharedFile ----------

  describe('updateSharedFile', () => {
    it('encrypts new content, updates file metadata IPNS, and publishes', async () => {
      const getFileIpnsKeyFn = vi.fn().mockResolvedValue(new Uint8Array(64).fill(0x88));
      const addFn = vi.fn().mockResolvedValue(undefined);

      await updateSharedFile({
        ctx: {
          apiUrl: 'http://localhost:3000',
          getAccessToken: async () => 'token',
        },
        folderKey: new Uint8Array(32).fill(1),
        ownerPublicKey: new Uint8Array(33).fill(3),
        recipientPublicKey: new Uint8Array(33).fill(4),
        shareId: 'share-123',
        addShareKeysFn: addFn,
        filePointer: {
          type: 'file',
          id: 'f1',
          name: 'test.txt',
          fileMetaIpnsName: 'k51fileipns',
          ipnsPrivateKeyEncrypted: 'enc',
          createdAt: 1000,
          modifiedAt: 1000,
        },
        newContent: new Uint8Array([10, 20, 30]),
        getFileIpnsKeyFn,
      });

      // Content encrypted
      expect(encryptAesGcm).toHaveBeenCalled();

      // Uploaded to IPFS
      expect(addToIpfs).toHaveBeenCalled();

      // File metadata updated and published
      const { updateFileMetadata } = await import('@cipherbox/sdk-core');
      expect(updateFileMetadata).toHaveBeenCalled();
      expect(batchPublishIpnsRecords).toHaveBeenCalled();
    });

    it('calls addShareKeysFn with updated file key', async () => {
      const getFileIpnsKeyFn = vi.fn().mockResolvedValue(new Uint8Array(64).fill(0x88));
      const addFn = vi.fn().mockResolvedValue(undefined);

      await updateSharedFile({
        ctx: {
          apiUrl: 'http://localhost:3000',
          getAccessToken: async () => 'token',
        },
        folderKey: new Uint8Array(32).fill(1),
        ownerPublicKey: new Uint8Array(33).fill(3),
        recipientPublicKey: new Uint8Array(33).fill(4),
        shareId: 'share-123',
        addShareKeysFn: addFn,
        filePointer: {
          type: 'file',
          id: 'f1',
          name: 'test.txt',
          fileMetaIpnsName: 'k51fileipns',
          ipnsPrivateKeyEncrypted: 'enc',
          createdAt: 1000,
          modifiedAt: 1000,
        },
        newContent: new Uint8Array([10]),
        getFileIpnsKeyFn,
      });

      expect(addFn).toHaveBeenCalledWith('share-123', [
        expect.objectContaining({ keyType: 'file', itemId: 'f1' }),
      ]);
    });

    it('throws when getFileIpnsKeyFn returns null', async () => {
      const getFileIpnsKeyFn = vi.fn().mockResolvedValue(null);

      await expect(
        updateSharedFile({
          ctx: {
            apiUrl: 'http://localhost:3000',
            getAccessToken: async () => 'token',
          },
          folderKey: new Uint8Array(32).fill(1),
          ownerPublicKey: new Uint8Array(33).fill(3),
          recipientPublicKey: new Uint8Array(33).fill(4),
          shareId: 'share-123',
          addShareKeysFn: vi.fn(),
          filePointer: {
            type: 'file',
            id: 'f1',
            name: 'test.txt',
            fileMetaIpnsName: 'k51fileipns',
            ipnsPrivateKeyEncrypted: 'enc',
            createdAt: 1000,
            modifiedAt: 1000,
          },
          newContent: new Uint8Array([10]),
          getFileIpnsKeyFn,
        })
      ).rejects.toThrow(/IPNS key/i);
    });
  });

  // ---------- updateSharePermission ----------

  describe('updateSharePermission', () => {
    it('calls the provided updatePermissionFn with correct params', async () => {
      const updateFn = vi.fn().mockResolvedValue(undefined);

      await updateSharePermission({
        shareId: 'share-456',
        permission: 'write',
        encryptedIpnsKey: 'wrapped-key',
        updatePermissionFn: updateFn,
      });

      expect(updateFn).toHaveBeenCalledWith('share-456', {
        permission: 'write',
        encryptedIpnsKey: 'wrapped-key',
      });
    });

    it('calls without encryptedIpnsKey when not provided', async () => {
      const updateFn = vi.fn().mockResolvedValue(undefined);

      await updateSharePermission({
        shareId: 'share-456',
        permission: 'read',
        updatePermissionFn: updateFn,
      });

      expect(updateFn).toHaveBeenCalledWith('share-456', {
        permission: 'read',
        encryptedIpnsKey: undefined,
      });
    });
  });
});

/**
 * @cipherbox/sdk - Shared-write operations
 *
 * Stateless functions for write operations on shared folders.
 * Extracted from: apps/web/src/hooks/useSharedNavigation.ts (write handlers)
 *
 * Each function takes explicit context (keys, IPNS state, callbacks) and
 * returns updated state. No React/Zustand/browser dependencies.
 *
 * Key wrapping convention for shared folders:
 * - FolderEntry/FilePointer fields wrap keys with the OWNER's public key
 *   (so the owner can access their own data)
 * - share_keys entries wrap keys with the RECIPIENT's public key
 *   (so the share recipient can access)
 */

import {
  encryptAesGcm,
  generateFileKey,
  generateIv,
  wrapKey,
  bytesToHex,
  generateRandomBytes,
  generateEd25519Keypair,
  deriveIpnsName,
} from '@cipherbox/crypto';
import {
  generateFileIpnsKeypair,
  encryptFolderMetadata,
  encryptFileMetadata,
  type FolderChild,
  type FolderEntry,
  type FilePointer,
  type FileMetadata,
  type FolderMetadata,
} from '@cipherbox/core';
import {
  updateFolderMetadataAndPublish,
  addToIpfs,
  batchPublishIpnsRecords,
  createAndPublishIpnsRecord,
  resolveFileMetadata,
  updateFileMetadata,
} from '@cipherbox/sdk-core';
import type { SdkContext } from '@cipherbox/sdk-core';

/**
 * Context for shared-write operations on a folder.
 * Provides all state needed to modify folder contents and publish changes.
 */
export type SharedWriteContext = {
  /** SDK context for IPFS/IPNS API access */
  ctx: SdkContext;
  /** Decrypted AES-256 folder key for the current folder */
  folderKey: Uint8Array;
  /** Ed25519 private key for signing IPNS publishes */
  ipnsPrivateKey: Uint8Array;
  /** IPNS name of the current folder */
  ipnsName: string;
  /** Current sequence number for conflict detection */
  sequenceNumber: bigint;
  /** Current folder children */
  children: FolderChild[];
  /** Sharer's secp256k1 public key (keys in FolderEntry/FilePointer wrap for owner) */
  ownerPublicKey: Uint8Array;
  /** Current user's secp256k1 public key (keys in share_keys wrap for recipient) */
  recipientPublicKey: Uint8Array;
  /** Share ID for addShareKeysFn calls */
  shareId: string;
  /** Callback to add share keys for the recipient */
  addShareKeysFn: (
    shareId: string,
    keys: Array<{ keyType: string; itemId: string; encryptedKey: string }>
  ) => Promise<void>;
};

// ---------------------------------------------------------------------------
// Function 1: uploadToSharedFolder
// ---------------------------------------------------------------------------

/**
 * Upload a file to a write-shared folder.
 *
 * Encrypts the file content, creates per-file IPNS metadata, adds the
 * FilePointer to folder children, publishes the updated folder, and
 * registers share_keys for the recipient.
 *
 * Key wrapping:
 * - fileKey wrapped with ownerPublicKey -> FilePointer.fileKeyEncrypted (owner access)
 * - fileKey wrapped with recipientPublicKey -> share_keys file key (recipient access)
 * - IPNS private key wrapped with ownerPublicKey -> FilePointer.ipnsPrivateKeyEncrypted
 * - IPNS private key wrapped with recipientPublicKey -> share_keys file-ipns key
 */
export async function uploadToSharedFolder(
  swCtx: SharedWriteContext,
  params: { data: Uint8Array; fileName: string; mimeType?: string }
): Promise<{
  updatedChildren: FolderChild[];
  newSequenceNumber: bigint;
  filePointer: FilePointer;
}> {
  const fileKey = generateFileKey();
  const iv = generateIv();

  try {
    // 1. Encrypt file content
    const ciphertext = await encryptAesGcm(params.data, fileKey, iv);

    // 2. Upload encrypted content to IPFS
    const { cid: contentCid } = await addToIpfs(swCtx.ctx, new Uint8Array(ciphertext));

    // 3. Wrap fileKey with owner's public key (for FilePointer)
    const ownerWrappedFileKey = await wrapKey(fileKey, swCtx.ownerPublicKey);
    const fileKeyEncrypted = bytesToHex(ownerWrappedFileKey);

    // 4. Generate IPNS keypair for file metadata
    const fileId = crypto.randomUUID();
    const mimeType = params.mimeType ?? 'application/octet-stream';
    const ipnsKeypair = await generateFileIpnsKeypair();

    try {
      // 5. Wrap IPNS private key for owner (FilePointer) and recipient (share_keys)
      const ownerWrappedIpnsKey = await wrapKey(ipnsKeypair.privateKey, swCtx.ownerPublicKey);
      const ipnsPrivateKeyEncrypted = bytesToHex(ownerWrappedIpnsKey);
      const recipientWrappedIpnsKey = await wrapKey(
        ipnsKeypair.privateKey,
        swCtx.recipientPublicKey
      );

      // 6. Create and encrypt file metadata
      const now = Date.now();
      const fileMeta: FileMetadata = {
        version: 'v1',
        cid: contentCid,
        fileKeyEncrypted,
        fileIv: bytesToHex(iv),
        size: params.data.length,
        mimeType,
        encryptionMode: 'GCM',
        createdAt: now,
        modifiedAt: now,
      };
      const encrypted = await encryptFileMetadata(fileMeta, swCtx.folderKey);

      // 7. Upload encrypted metadata to IPFS
      const jsonStr = JSON.stringify(encrypted);
      const metadataBytes = new TextEncoder().encode(jsonStr);
      const { cid: metadataCid } = await addToIpfs(swCtx.ctx, metadataBytes);

      // 8. Create and publish file IPNS record
      // Use createAndPublishIpnsRecord for single file IPNS, then batch publish
      const ipnsLifetimeMs = 24 * 60 * 60 * 1000;
      const { createIpnsRecord, marshalIpnsRecord } = await import('@cipherbox/core');
      const record = await createIpnsRecord(
        ipnsKeypair.privateKey,
        `/ipfs/${metadataCid}`,
        1n,
        ipnsLifetimeMs
      );
      const recordBytes = marshalIpnsRecord(record);
      let binary = '';
      for (let i = 0; i < recordBytes.length; i++) {
        binary += String.fromCharCode(recordBytes[i]);
      }
      const recordBase64 = btoa(binary);

      await batchPublishIpnsRecords(
        [
          {
            ipnsName: ipnsKeypair.ipnsName,
            recordBase64,
            metadataCid,
            recordType: 'file' as const,
          },
        ],
        swCtx.ctx
      );

      // 9. Build FilePointer (owner-wrapped keys)
      const filePointer: FilePointer = {
        type: 'file',
        id: fileId,
        name: params.fileName,
        fileMetaIpnsName: ipnsKeypair.ipnsName,
        ipnsPrivateKeyEncrypted,
        createdAt: now,
        modifiedAt: now,
      };

      // 10. Add file to folder children and publish
      const updatedChildren = [...swCtx.children, filePointer];
      const { newSequenceNumber } = await updateFolderMetadataAndPublish({
        children: updatedChildren,
        folderKey: swCtx.folderKey,
        ipnsPrivateKey: swCtx.ipnsPrivateKey,
        ipnsName: swCtx.ipnsName,
        sequenceNumber: swCtx.sequenceNumber,
        ctx: swCtx.ctx,
      });

      // 11. Add share_keys for recipient (file + file-ipns)
      const recipientWrappedFileKey = await wrapKey(fileKey, swCtx.recipientPublicKey);
      try {
        await swCtx.addShareKeysFn(swCtx.shareId, [
          { keyType: 'file', itemId: fileId, encryptedKey: bytesToHex(recipientWrappedFileKey) },
          {
            keyType: 'file-ipns',
            itemId: fileId,
            encryptedKey: bytesToHex(recipientWrappedIpnsKey),
          },
        ]);
      } catch (err) {
        console.warn('[shared-write] Failed to add share_keys for uploaded file:', err);
      }

      return { updatedChildren, newSequenceNumber, filePointer };
    } finally {
      ipnsKeypair.privateKey.fill(0);
    }
  } finally {
    fileKey.fill(0);
  }
}

// ---------------------------------------------------------------------------
// Function 2: createSharedSubfolder
// ---------------------------------------------------------------------------

/**
 * Create a subfolder in a write-shared folder.
 *
 * Generates an Ed25519 keypair and AES-256 folder key, wraps with owner's
 * key for FolderEntry, publishes empty subfolder IPNS, adds FolderEntry to
 * parent, publishes parent, and registers share_keys for the recipient.
 */
export async function createSharedSubfolder(
  swCtx: SharedWriteContext,
  params: { name: string }
): Promise<{
  updatedChildren: FolderChild[];
  newSequenceNumber: bigint;
  folderEntry: FolderEntry;
}> {
  // Generate Ed25519 keypair for the subfolder IPNS
  const keypair = await generateEd25519Keypair();
  const subfolderIpnsName = await deriveIpnsName(keypair.publicKey);

  // Generate AES-256 folder key for the subfolder
  const subfolderKey = generateRandomBytes(32);

  try {
    // 1. Wrap keys with owner's public key (for FolderEntry)
    const wrappedFolderKey = await wrapKey(subfolderKey, swCtx.ownerPublicKey);
    const wrappedIpnsKey = await wrapKey(keypair.privateKey, swCtx.ownerPublicKey);

    // 2. Create and encrypt empty folder metadata
    const subfolderMetadata: FolderMetadata = { version: 'v2', children: [] };
    const encrypted = await encryptFolderMetadata(subfolderMetadata, subfolderKey);
    const jsonStr = JSON.stringify(encrypted);
    const encryptedBytes = new TextEncoder().encode(jsonStr);
    const { cid: subfolderCid } = await addToIpfs(swCtx.ctx, encryptedBytes);

    // 3. Publish subfolder IPNS
    await createAndPublishIpnsRecord({
      ipnsPrivateKey: keypair.privateKey,
      ipnsName: subfolderIpnsName,
      metadataCid: subfolderCid,
      sequenceNumber: 1n,
      ctx: swCtx.ctx,
    });

    // 4. Create FolderEntry for the parent
    const folderId = crypto.randomUUID();
    const folderEntry: FolderEntry = {
      type: 'folder',
      id: folderId,
      name: params.name,
      ipnsName: subfolderIpnsName,
      ipnsPrivateKeyEncrypted: bytesToHex(wrappedIpnsKey),
      folderKeyEncrypted: bytesToHex(wrappedFolderKey),
      createdAt: Date.now(),
      modifiedAt: Date.now(),
    };

    // 5. Add to parent folder and publish
    const updatedChildren = [...swCtx.children, folderEntry];
    const { newSequenceNumber } = await updateFolderMetadataAndPublish({
      children: updatedChildren,
      folderKey: swCtx.folderKey,
      ipnsPrivateKey: swCtx.ipnsPrivateKey,
      ipnsName: swCtx.ipnsName,
      sequenceNumber: swCtx.sequenceNumber,
      ctx: swCtx.ctx,
    });

    // 6. Add share_keys for recipient (folder + folder-ipns)
    const recipientWrappedFolderKey = await wrapKey(subfolderKey, swCtx.recipientPublicKey);
    const recipientWrappedIpnsKey = await wrapKey(keypair.privateKey, swCtx.recipientPublicKey);
    try {
      await swCtx.addShareKeysFn(swCtx.shareId, [
        {
          keyType: 'folder',
          itemId: folderId,
          encryptedKey: bytesToHex(recipientWrappedFolderKey),
        },
        {
          keyType: 'folder-ipns',
          itemId: folderId,
          encryptedKey: bytesToHex(recipientWrappedIpnsKey),
        },
      ]);
    } catch (err) {
      console.warn('[shared-write] Failed to add share_keys for subfolder:', err);
    }

    return { updatedChildren, newSequenceNumber, folderEntry };
  } finally {
    subfolderKey.fill(0);
    keypair.privateKey.fill(0);
  }
}

// ---------------------------------------------------------------------------
// Function 3: renameInSharedFolder
// ---------------------------------------------------------------------------

/**
 * Rename an item in a write-shared folder.
 *
 * Maps over children to update the name and modifiedAt, then publishes
 * the updated folder metadata.
 */
export async function renameInSharedFolder(
  swCtx: SharedWriteContext,
  params: { itemId: string; newName: string }
): Promise<{ updatedChildren: FolderChild[]; newSequenceNumber: bigint }> {
  const updatedChildren = swCtx.children.map((child) =>
    child.id === params.itemId
      ? { ...child, name: params.newName, modifiedAt: Date.now() }
      : child
  );

  const { newSequenceNumber } = await updateFolderMetadataAndPublish({
    children: updatedChildren,
    folderKey: swCtx.folderKey,
    ipnsPrivateKey: swCtx.ipnsPrivateKey,
    ipnsName: swCtx.ipnsName,
    sequenceNumber: swCtx.sequenceNumber,
    ctx: swCtx.ctx,
  });

  return { updatedChildren, newSequenceNumber };
}

// ---------------------------------------------------------------------------
// Function 4: deleteFromSharedFolder
// ---------------------------------------------------------------------------

/**
 * Delete an item from a write-shared folder.
 *
 * Filters the item from children and publishes the updated folder metadata.
 */
export async function deleteFromSharedFolder(
  swCtx: SharedWriteContext,
  params: { itemId: string }
): Promise<{ updatedChildren: FolderChild[]; newSequenceNumber: bigint }> {
  const updatedChildren = swCtx.children.filter((child) => child.id !== params.itemId);

  const { newSequenceNumber } = await updateFolderMetadataAndPublish({
    children: updatedChildren,
    folderKey: swCtx.folderKey,
    ipnsPrivateKey: swCtx.ipnsPrivateKey,
    ipnsName: swCtx.ipnsName,
    sequenceNumber: swCtx.sequenceNumber,
    ctx: swCtx.ctx,
  });

  return { updatedChildren, newSequenceNumber };
}

// ---------------------------------------------------------------------------
// Function 5: updateSharedFile
// ---------------------------------------------------------------------------

/**
 * Update a file's content in a write-shared context.
 *
 * Encrypts new content, uploads to IPFS, resolves current file metadata,
 * updates the file metadata IPNS record, and refreshes the recipient's
 * share_key for the file.
 *
 * Does NOT modify folder metadata (the FilePointer stays the same).
 */
export async function updateSharedFile(params: {
  ctx: SdkContext;
  folderKey: Uint8Array;
  ownerPublicKey: Uint8Array;
  recipientPublicKey: Uint8Array;
  shareId: string;
  addShareKeysFn: (
    shareId: string,
    keys: Array<{ keyType: string; itemId: string; encryptedKey: string }>
  ) => Promise<void>;
  filePointer: FilePointer;
  newContent: Uint8Array;
  /** Callback to get the file's IPNS private key (checks share_keys then FilePointer fallback) */
  getFileIpnsKeyFn: (itemId: string) => Promise<Uint8Array | null>;
}): Promise<void> {
  // 1. Encrypt new content
  const fileKey = generateFileKey();
  const iv = generateIv();

  try {
    const ciphertext = await encryptAesGcm(params.newContent, fileKey, iv);

    // 2. Upload encrypted content to IPFS
    const { cid: contentCid } = await addToIpfs(params.ctx, new Uint8Array(ciphertext));

    // 3. Wrap fileKey with owner's public key
    const ownerWrappedKey = await wrapKey(fileKey, params.ownerPublicKey);
    const fileKeyEncrypted = bytesToHex(ownerWrappedKey);

    // 4. Get the file's IPNS private key
    const ipnsPrivKey = await params.getFileIpnsKeyFn(params.filePointer.id);
    if (!ipnsPrivKey) {
      throw new Error('Cannot update: no file IPNS key available');
    }

    try {
      // 5. Resolve current file metadata
      const { metadata: currentMeta } = await resolveFileMetadata(
        params.filePointer.fileMetaIpnsName,
        params.folderKey,
        params.ctx
      );

      // 6. Update file metadata
      const { ipnsRecord } = await updateFileMetadata({
        fileIpnsPrivateKey: ipnsPrivKey,
        fileMetaIpnsName: params.filePointer.fileMetaIpnsName,
        folderKey: params.folderKey,
        currentMetadata: currentMeta,
        updates: {
          cid: contentCid,
          fileKeyEncrypted,
          fileIv: bytesToHex(iv),
          size: params.newContent.length,
          encryptionMode: 'GCM',
        },
        createVersion: false,
        ctx: params.ctx,
      });

      // 7. Publish updated file IPNS record
      await batchPublishIpnsRecords(
        [{ ...ipnsRecord, recordType: 'file' as const }],
        params.ctx
      );

      // 8. Update share_key for recipient
      const recipientWrappedKey = await wrapKey(fileKey, params.recipientPublicKey);
      try {
        await params.addShareKeysFn(params.shareId, [
          {
            keyType: 'file',
            itemId: params.filePointer.id,
            encryptedKey: bytesToHex(recipientWrappedKey),
          },
        ]);
      } catch (err) {
        console.warn('[shared-write] Failed to update share_key after file edit:', err);
      }
    } finally {
      ipnsPrivKey.fill(0);
    }
  } finally {
    fileKey.fill(0);
  }
}

// ---------------------------------------------------------------------------
// Function 6: updateSharePermission
// ---------------------------------------------------------------------------

/**
 * Update a share's permission level.
 *
 * Thin callback wrapper consistent with the existing revokeShare pattern.
 */
export async function updateSharePermission(params: {
  shareId: string;
  permission: string;
  encryptedIpnsKey?: string;
  updatePermissionFn: (
    shareId: string,
    body: { permission: string; encryptedIpnsKey?: string }
  ) => Promise<void>;
}): Promise<void> {
  await params.updatePermissionFn(params.shareId, {
    permission: params.permission,
    encryptedIpnsKey: params.encryptedIpnsKey,
  });
}

